class Solution {
public:
    vector<int> gardenNoAdj(int n, vector<vector<int>>& paths) {
        vector<vector<int>> adj(n + 1);
        for (auto& p : paths) {
            adj[p[0]].push_back(p[1]);
            adj[p[1]].push_back(p[0]);
        }
        vector<int> ans(n, 0);
        for (int i = 1; i <= n; i++) {
            bool used[5] = {};
            for (int nb : adj[i]) {
                if (ans[nb - 1] != 0) used[ans[nb - 1]] = true;
            }
            for (int c = 1; c <= 4; c++) {
                if (!used[c]) {
                    ans[i - 1] = c;
                    break;
                }
            }
        }
        return ans;
    }
};
